    """Insert a value into the BST."""
    if self._root is None:
        self._root = TreeNode(value)
        return
    cur = self._root
    while True:
        if value < cur.value:
            if cur.left is None:
                cur.left = TreeNode(value)
                return
            cur = cur.left
        else:
            if cur.right is None:
                cur.right = TreeNode(value)
